            // the API (`/^(?:[0-9a-fA-F]{2})+$/`, `update-grant.dto.ts`) and
            // decoded via `Buffer.from(.., 'hex')` — must be hex, NOT base64.
            let encrypted_read_key = hex::encode(&wrapped);
