1	/**
2	 * TDD tests for Phase 68 Plan 05: scope-exit read-key rotation and
3	 * reconcile-before-publish wiring at the SDK client chokepoint (client.ts).
4	 *
5	 * Covers:
6	 *  - Task 1: ReconcileStaleError / reconcile-before-publish (SC#3 / D-04)
7	 *  - Task 2: maybeRotateOnScopeExit wiring + injection seam (SC#2 / SC#4)
8	 *  - Task 3: moveItem dest-before-source publish ordering (D-12)
9	 */
10	import { describe, it, expect, vi, beforeEach } from 'vitest';
11	import { CipherBoxClient, ReconcileStaleError } from '../client';
12	import { createTestConfig, setupFolder } from './helpers';
13	import { SequenceRegressionError } from '../state/rotation-high-water';
