17	
18	// ── crypto mock ──────────────────────────────────────────────────────────
19	// Keeps the REAL AEAD primitives (sealAesGcmAad/unsealAesGcmAad/buildNodeAad/
20	// CryptoError) via importOriginal -- reconcileFolderSequence's SC#5/D-09
21	// fetch+unseal now calls the real unsealNode (from the un-mocked
22	// @cipherbox/core below), which in turn needs these real primitives.
23	vi.mock('@cipherbox/crypto', async (importOriginal) => {
24	  const actual = await importOriginal<typeof import('@cipherbox/crypto')>();
25	  return {
26	    ...actual,
27	    clearBytes: vi.fn((arr: Uint8Array) => arr.fill(0)),
28	    unwrapKey: vi.fn().mockResolvedValue(new Uint8Array(64).fill(0x55)),
29	    hexToBytes: vi.fn((hex: string) => new Uint8Array(hex.length / 2)),
30	  };
31	});
32	
33	// ── sdk-core mock ────────────────────────────────────────────────────────
34	vi.mock('@cipherbox/sdk-core', async (importOriginal) => {
35	  const actual = await importOriginal<typeof import('@cipherbox/sdk-core')>();
36	  return {
37	    ...actual,
38	    loadFolderMetadata: vi.fn(),
39	    updateFolderMetadataAndPublish: vi.fn(),
40	    renameInFolder: vi.fn(),
41	    deleteFromFolder: vi.fn(),
42	    moveItem: vi.fn(),
43	    resolveIpnsRecord: vi.fn(),
44	    fetchFromIpfs: vi.fn(),
45	    rotateReadFromNode: vi.fn(),
46	  };
47	});
48	
49	// ── @cipherbox/core mock (moveItem's FLAG-63-U2 re-seal) ────────────────
50	vi.mock('@cipherbox/core', async (importOriginal) => {
51	  const actual = await importOriginal<typeof import('@cipherbox/core')>();
52	  return {
53	    ...actual,
54	    sealChildReadKey: vi.fn().mockResolvedValue('resealed-dest-hex'),
55	    unsealChildReadKey: vi.fn().mockResolvedValue(new Uint8Array(32).fill(0x42)),
56	  };
57	});
58	
59	// ── bin / share mocks (not under test, silence missing-module errors) ────
60	vi.mock('../bin', () => ({
61	  loadBin: vi.fn(),
62	  addToBin: vi.fn(),
63	  restoreFromBin: vi.fn(),
64	  permanentDeleteFromBin: vi.fn(),
65	  emptyBin: vi.fn(),
