72	}));
73	
74	import * as sdkCore from '@cipherbox/sdk-core';
75	import * as binOps from '../bin';
76	
77	const FOLDER_IPNS = 'folder-ipns';
78	const SRC_IPNS = 'src-ipns';
79	const DEST_IPNS = 'dest-ipns';
80	
81	/** Mock resolveIpnsRecord to return a matching sequenceNumber for every call. */
82	function mockResolveMatching(sequenceNumber: bigint) {
83	  vi.mocked(sdkCore.resolveIpnsRecord).mockResolvedValue({
84	    cid: 'bafyresolved',
85	    sequenceNumber,
86	    signatureVerified: true,
87	  });
88	}
89	
90	/**
91	 * Mocks fetchFromIpfs to return a real, AAD-bound PublishedNode envelope at
92	 * `generation`, sealed under `folderKey` -- so reconcileFolderSequence's
93	 * SC#5/D-09 fetch+unseal (a REAL unsealNode call, not mocked) succeeds and
94	 * yields exactly `generation` to the enforceResolved gate.
