async fn rotate_one_inner<D: RotationDeps>(
    deps: &D,
    node_id: Option<&str>,
    node_ipns_name: &str,
    parent_read_key: &[u8],
    job_record: &mut RotationJobRecord,
    children_override: Option<&[SealedChildRef]>,
