29	/** A decoded sent-share row, enriched with `shareRootIpnsName` for the FolderTree lookup below. */
30	type DecodedSentGrant = GrantRow & { shareRootIpnsName: string };
31	
32	/**
33	 * Fetch + decode every share the owner has sent.
34	 *
35	 * `recipientPublicKey` is hex-encoded on the wire (0x04...); decoded to
36	 * `Uint8Array` here for the ECIES re-wrap inside the SDK driver.
37	 *
38	 * `isRevoked` is always `false`: this project's shares table uses hard-delete
39	 * revocation (D-11 forward-only revocation, project convention -- revoke =
40	 * DELETE, never a soft `revoked_at` flag), so a revoked grant row is removed
41	 * from the table entirely and never appears in `GET /shares/sent`. Every row
42	 * returned here is therefore an active (non-revoked) grant.
43	 */
44	async function decodeSentGrants(): Promise<DecodedSentGrant[]> {
45	  const decoded: DecodedSentGrant[] = [];
46	  // Paginate through ALL sent shares (the API caps limit at 100 per page) --
47	  // a first-page-only read would leave grants beyond page 1 unreconciled.
48	  const pageSize = 100;
49	  let offset = 0;
50	  for (;;) {
51	    const { shares, total } = await sharesControllerGetSentShares({ limit: pageSize, offset });
52	    for (const share of shares) {
53	      try {
54	        // Wire format is bare hex, but normalize a 0x prefix defensively --
55	        // hexToBytes would otherwise choke and one bad row must not abort the
56	        // whole reconcile sweep.
57	        const bareHex = share.recipientPublicKey.startsWith('0x')
58	          ? share.recipientPublicKey.slice(2)
59	          : share.recipientPublicKey;
60	        decoded.push({
61	          shareId: share.shareId,
62	          recipientPublicKey: hexToBytes(bareHex),
63	          isRevoked: false,
64	          rootNodeId: share.rootNodeId,
65	          shareRootIpnsName: share.shareRootIpnsName,
66	        });
67	      } catch (error) {
68	        logger.error(
69	          `[owner-reconcile] Skipping sent grant ${share.shareId}: recipientPublicKey decode failed:`,
70	          safeError(error)
71	        );
72	      }
73	    }
74	    offset += shares.length;
75	    if (offset >= total || shares.length === 0) break;
76	  }
77	  return decoded;
78	}
79	
80	async function listSentGrants(): Promise<GrantRow[]> {
81	  const decoded = await decodeSentGrants();
82	  return decoded.map(({ shareId, recipientPublicKey, isRevoked, rootNodeId }) => ({
83	    shareId,
84	    recipientPublicKey,
85	    isRevoked,
86	    rootNodeId,
87	  }));
88	}
