1	/**
2	 * Rotation Driver — concrete web callbacks for the SDK's scope-exit rotation
3	 * injection seam (68-05) + D-02/D-03 progress-badge wiring + D-09 multi-tab
4	 * leader election + resumable durable job checkpoint.
5	 *
6	 * THIN, UNTESTED glue (per docs/TESTING.md doctrine): all monotonic-max /
7	 * idempotency / CAS-409 re-merge logic lives in the SDK (68-01/63/64) and is
8	 * unit-proven there. This module only maps rotation lifecycle signals onto
9	 * the web's durable IndexedDB checkpoint + the `rotation.store` badge + the
10	 * `multi-tab-lock` leader election. Proven end-to-end (badge lifecycle +
11	 * resume-after-reload) by the 68-10 web-e2e rotation-ux spec.
12	 *
13	 * @security
14	 * `persistJob` NEVER serialises key material (Pitfall 4 / T-68-83): it
15	 * writes only `rootNodeId`, `status`, `completedNodeIds`, and the frontier's
16	 * `nodeIpnsName`s to IndexedDB — never `parentReadKey`/`ipnsPrivateKey`
17	 * bytes. It also never zeros/mutates the caller's `RotationJobRecord`
18	 * buffers — this callback is a read-only observer, not a terminal key owner
19	 * (D-09; see `rotation/engine.ts`'s zeroization docblocks).
20	 *
21	 * @security
22	 * Badge lifecycle timing note: the SDK chokepoint (`performScopeExitRotation`
23	 * in `packages/sdk/src/client.ts`) awaits the ENTIRE rotation (root cut +
24	 * tail walk) before the triggering mutation resolves — there is no separate
25	 * "root cut is starting" hook exposed today. `rotateReadFromNode` DOES call
26	 * `persistCallback` (this module's `persistJob`) as its first checkpoint
27	 * immediately after the root commits (the "high-value early checkpoint"),
28	 * and again after every subsequent per-node tail commit, and finally once
29	 * more with `status: 'complete'`. This module therefore treats the FIRST
30	 * `persistJob` call for a given `rootNodeId` as the root-cut signal
31	 * (`beginRootCut`) and every SUBSEQUENT call for the same root as tail-walk
32	 * progress (`beginTailWalk`), before resetting on the terminal call.
33	 */
34	
35	import type { RotationClientCallbacks, LocalGrantRecord } from '@cipherbox/sdk';
36	import type { RotationJobRecord } from '@cipherbox/sdk-core';
37	import { useShareStore } from '../stores/share.store';
38	import { useRotationStore } from '../stores/rotation.store';
39	import { withTailWalkLeader } from '../lib/multi-tab-lock';
40	import { logger } from '../lib/logger';
41	
42	// ---------------------------------------------------------------------------
43	// Durable job checkpoint (metadata-only — never key material, Pitfall 4)
44	// ---------------------------------------------------------------------------
45	
46	const JOB_DB_NAME = 'cipherbox-rotation-jobs';
47	const JOB_DB_VERSION = 1;
48	const JOB_STORE_NAME = 'jobs';
49	
50	/** Sanitized, durable projection of a `RotationJobRecord` — metadata only, NEVER key bytes. */
51	type DurableJobCheckpoint = {
52	  rootNodeId: string;
53	  status: RotationJobRecord['status'];
54	  completedNodeIds: string[];
55	  frontierIpnsNames: string[];
56	  updatedAt: number;
57	};
58	
59	/**
60	 * Cached shared connection promise (mirrors `rotation-state.service.ts`'s
61	 * `openRotationDB` connection-caching idiom): checkpoint calls previously
62	 * opened a FRESH `indexedDB.open` connection every call and never closed it,
63	 * leaking one connection per persist/delete/getAll invocation for the
64	 * lifetime of the tab. Callers now share this single open connection.
65	 *
66	 * Invalidated (set back to `null`) on `onversionchange`/`onclose` — e.g. a
67	 * second tab upgrading the DB version, or the connection being force-closed —
68	 * so the NEXT call transparently reopens rather than reusing a dead handle.
69	 */
70	let jobDBPromise: Promise<IDBDatabase> | null = null;
71	
72	function openJobDB(): Promise<IDBDatabase> {
73	  if (jobDBPromise) return jobDBPromise;
74	
75	  jobDBPromise = new Promise((resolve, reject) => {
76	    const request = indexedDB.open(JOB_DB_NAME, JOB_DB_VERSION);
77	    request.onupgradeneeded = () => {
78	      const db = request.result;
79	      if (!db.objectStoreNames.contains(JOB_STORE_NAME)) {
80	        db.createObjectStore(JOB_STORE_NAME, { keyPath: 'rootNodeId' });
81	      }
82	    };
83	    request.onsuccess = () => {
84	      const db = request.result;
85	      // Another connection (another tab) wants to upgrade the DB version, or
86	      // this connection was closed out from under us — drop the cache so the
87	      // next caller reopens a fresh connection instead of using a dead one.
88	      db.onversionchange = () => {
89	        db.close();
90	        jobDBPromise = null;
91	      };
92	      db.onclose = () => {
93	        jobDBPromise = null;
94	      };
95	      resolve(db);
96	    };
97	    request.onerror = () => {
98	      jobDBPromise = null;
99	      reject(request.error);
100	    };
101	  });
102	
103	  return jobDBPromise;
104	}
105	
106	/**
107	 * Close the cached job-DB connection, if open, and drop the cache so the
108	 * next checkpoint call reopens fresh. Exposed for callers that want to
109	 * release the handle on logout (mirrors the `onversionchange`/`onclose`
110	 * invalidation above) — not currently wired into the app's logout flow
111	 * (`lib/clear-user-stores.ts` is outside this plan's scope), but available
112	 * for that future wiring without another change to this module.
113	 */
114	export async function closeJobDB(): Promise<void> {
115	  if (!jobDBPromise) return;
116	  try {
117	    const db = await jobDBPromise;
118	    db.close();
119	  } catch {
120	    // Connection never successfully opened — nothing to close.
121	  } finally {
122	    jobDBPromise = null;
123	  }
